CREATE FUNCTION public.cotironda_piloto_v2_commercial_checkpoint(
 p_chat_hmac text,p_id uuid,p_revision bigint,p_lease uuid,
 p_action text,p_expected integer,p_total integer,p_manifest text,p_nonce text,p_ciphertext text,p_pause boolean
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO ''
AS $checkpoint$
DECLARE b text; g cotironda_piloto_privado.v2_buyer_conversations%ROWTYPE;
 old cotironda_piloto_privado.v2_commercial_route_checkpoint%ROWTYPE;
 manifest text; cursor_next integer;
BEGIN
 IF p_action IS NULL OR p_action NOT IN ('load','save') THEN RETURN jsonb_build_object('state','invalid'); END IF;
 SELECT key INTO b FROM cotironda_piloto_privado.participants WHERE chat_hmac=p_chat_hmac AND participant_role='buyer' AND consent_at IS NOT NULL AND opted_out_at IS NULL FOR UPDATE;
 IF b IS NULL THEN RETURN jsonb_build_object('state','not_authorized'); END IF;
 SELECT * INTO g FROM cotironda_piloto_privado.v2_buyer_conversations WHERE id=p_id AND buyer_key=b AND chat_hmac=p_chat_hmac AND revision=p_revision AND state='processing' AND lease=p_lease AND lease_until>clock_timestamp() AND request_id IS NULL FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('state','stale'); END IF;
 IF EXISTS(SELECT 1 FROM cotironda_piloto_privado.v2_buyer_conversation_sources s LEFT JOIN cotironda_piloto_privado.whapi_inbox m USING(message_hmac)
 WHERE s.conversation_id=p_id AND (m.message_hmac IS NULL OR m.chat_hmac IS DISTINCT FROM p_chat_hmac OR m.participant_key IS DISTINCT FROM b OR m.plaintext_sha256 IS DISTINCT FROM s.source_sha256 OR m.kind IS DISTINCT FROM s.kind OR m.request_id IS NOT NULL))
 THEN RETURN jsonb_build_object('state','source_changed'); END IF;
 SELECT encode(sha256(convert_to(string_agg(s.message_hmac||':'||s.source_sha256||':'||s.kind,'|' ORDER BY s.received_at,s.message_hmac),'UTF8')),'hex') INTO manifest FROM cotironda_piloto_privado.v2_buyer_conversation_sources s WHERE s.conversation_id=p_id;
 IF manifest IS NULL THEN RETURN jsonb_build_object('state','source_changed'); END IF;
 SELECT * INTO old FROM cotironda_piloto_privado.v2_commercial_route_checkpoint WHERE conversation_id=p_id FOR UPDATE;
 IF old.conversation_id IS NOT NULL AND old.revision<>p_revision THEN
  DELETE FROM cotironda_piloto_privado.v2_commercial_route_checkpoint WHERE conversation_id=p_id;
  SELECT * INTO old FROM cotironda_piloto_privado.v2_commercial_route_checkpoint WHERE conversation_id=p_id;
 END IF;
 IF old.conversation_id IS NOT NULL AND (old.manifest_sha<>manifest OR old.expires_at<=clock_timestamp()) THEN RETURN jsonb_build_object('state','checkpoint_invalid'); END IF;
 IF p_action='load' THEN
  IF old.conversation_id IS NULL THEN RETURN jsonb_build_object('state','none','manifest',manifest); END IF;
  RETURN jsonb_build_object('state','snapshot','manifest',manifest,'cursor',old.cursor_no,'total',old.total_groups,'nonce',old.nonce,'ciphertext',old.ciphertext);
 END IF;
 IF p_manifest IS DISTINCT FROM manifest OR p_total IS NULL OR p_total NOT BETWEEN 1 AND 200 OR p_expected IS NULL OR p_expected NOT BETWEEN -1 AND 199 OR p_pause IS NULL
 OR p_nonce IS NULL OR p_nonce!~'^[A-Za-z0-9+/]{16}$' OR p_ciphertext IS NULL OR length(p_ciphertext) NOT BETWEEN 24 AND 16777216 OR p_ciphertext!~'^[A-Za-z0-9+/=]+$'
 THEN RETURN jsonb_build_object('state','invalid_snapshot'); END IF;
 cursor_next:=p_expected+1;
 IF cursor_next>p_total OR (p_pause AND cursor_next=p_total) OR (old.conversation_id IS NULL AND p_expected<>-1) OR (old.conversation_id IS NOT NULL AND (p_expected<>old.cursor_no OR p_total<>old.total_groups)) THEN RETURN jsonb_build_object('state','checkpoint_conflict'); END IF;
 IF EXISTS(SELECT 1 FROM cotironda_piloto_privado.ai_usage_calls_mvp264 WHERE participant_key=b AND state='reserved') THEN RETURN jsonb_build_object('state','meter_busy'); END IF;
 INSERT INTO cotironda_piloto_privado.v2_commercial_route_checkpoint(conversation_id,revision,manifest_sha,cursor_no,total_groups,nonce,ciphertext,expires_at)
 VALUES(p_id,p_revision,manifest,cursor_next,p_total,p_nonce,p_ciphertext,coalesce(old.expires_at,clock_timestamp()+interval '30 minutes'))
 ON CONFLICT(conversation_id) DO UPDATE SET cursor_no=excluded.cursor_no,nonce=excluded.nonce,ciphertext=excluded.ciphertext;
 IF p_pause THEN UPDATE cotironda_piloto_privado.v2_buyer_conversations SET state='collecting',lease=NULL,lease_until=NULL,ready_at=clock_timestamp()+interval '15 seconds' WHERE id=p_id; END IF;
 RETURN jsonb_build_object('state',CASE WHEN p_pause THEN 'queued' ELSE 'saved' END,'cursor',cursor_next);
END
$checkpoint$;
REVOKE ALL ON FUNCTION public.cotironda_piloto_v2_commercial_checkpoint(text,uuid,bigint,uuid,text,integer,integer,text,text,text,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.cotironda_piloto_v2_commercial_checkpoint(text,uuid,bigint,uuid,text,integer,integer,text,text,text,boolean) TO service_role;
