/** One resumable routing step. Caller must encrypt and bind buyer, conversation, revision, manifest and cursor to AAD; SQL CAS commits and requeues. */
export function iniciarCheckpointComercial({pedido,grupos,meta,manifest}){
 if(!pedido||!Array.isArray(pedido.articulos)||!Array.isArray(grupos)||!grupos.length||grupos.length>200||!/^[a-f0-9]{64}$/.test(manifest)||!meta)return null;
 const keys=grupos.flat().map(x=>x.clave);
 if(!keys.length||new Set(keys).size!==keys.length)return null;
 return {version:1,pedido,grupos,meta,manifest,cursor:0,resultados:[]};
}
export async function avanzarCheckpointComercial({snapshot,manifest,route,authorize,remainingCalls,deadlineMs,now=Date.now}){
 const fail=motivo=>({estado:'sin_avance',motivo});
 if(!snapshot||snapshot.version!==1||snapshot.manifest!==manifest||!Number.isSafeInteger(snapshot.cursor)||snapshot.cursor<0||!Array.isArray(snapshot.grupos)||!Array.isArray(snapshot.resultados)||snapshot.resultados.length!==snapshot.cursor||snapshot.cursor>snapshot.grupos.length)return fail('snapshot_invalido');
 const {pedido,grupos,cursor}=snapshot;
 const all=grupos.flat(),keys=all.map(x=>x.clave);
 if(new Set(keys).size!==keys.length)return fail('snapshot_invalido');
 const checked=authorize(pedido,all,[]);
 if(checked.estado!=='ruteo_valido_para_preparacion'||checked.cobertura.length!==pedido.articulos.length)return fail('catalogo_invalido');
 const success=new Set(['productos_en_catalogo_y_zona_comprobados','coincidencias_requieren_correccion','coincidencias_parciales_verificadas','equivalencias_no_demostradas_en_revision_interna']);
 const valid=(result,group)=>{
  if(!result||result.whatsappEnviado!==false||!success.has(result.motivo)||!Array.isArray(result.propuestas)||!Array.isArray(result.revisionTecnica)||result.cobertura?.length!==pedido.articulos.length)return false;
  const verified=authorize(pedido,group,result.propuestas);
  return verified.estado==='ruteo_valido_para_preparacion'&&verified.propuestas.length===result.propuestas.length&&verified.propuestas.reduce((n,x)=>n+x.correspondencias.length,0)===result.propuestas.reduce((n,x)=>n+x.correspondencias.length,0);
 };
 if(snapshot.resultados.some((res,i)=>!valid(res,grupos[i])))return fail('snapshot_resultado_invalido');
 if(cursor===grupos.length){
  const proposals=snapshot.resultados.flatMap(r=>r.propuestas);
  const final=authorize(pedido,all,proposals);
  if(final.estado!=='ruteo_valido_para_preparacion'||final.propuestas.length!==proposals.length)return fail('resultado_no_conciliado');
  const revisionTecnica=snapshot.resultados.flatMap(r=>r.revisionTecnica);
  return {estado:'completo',resultado:{...final,propuestas:proposals,revisionTecnica,estado:!proposals.length&&revisionTecnica.length?'requiere_revision':final.estado},snapshot};
 }
 if(!Number.isFinite(deadlineMs)||deadlineMs-now()<120000||remainingCalls()<2)return fail('presupuesto_o_plazo_insuficiente');
 let result;
 try{result=await route(pedido,grupos[cursor]);}catch{return fail('lote_no_verificable')}
 if(!valid(result,grupos[cursor]))return fail('lote_no_verificable');
 return {estado:'guardar',expected:cursor,snapshot:{...snapshot,cursor:cursor+1,resultados:[...snapshot.resultados,result]}};
}
